function Person(name) {
  // 1. một object rỗng được tạo
  // 2. prototype của nó = Person.prototype
  // 3. this = object đó, rồi thân hàm chạy
  this.name = name
  // 4. tự động return this — trừ khi bạn return một object khác
}

const p = new Person('Định')
p.name                              // 'Định'
Object.getPrototypeOf(p) === Person.prototype   // true

function myNew(Ctor, ...args) {
  const obj = Object.create(Ctor.prototype)   // bước 1 + 2
  const ret = Ctor.apply(obj, args)           // bước 3
  return typeof ret === 'object' && ret !== null ? ret : obj   // bước 4
}

