function debounceAsync(fn, wait) {
  let timer
  let pending
  return (...args) => {
    clearTimeout(timer)
    pending ??= Promise.withResolvers()
    timer = setTimeout(async () => {
      const p = pending
      pending = null
      try { p.resolve(await fn(...args)) } catch (e) { p.reject(e) }
    }, wait)
    return pending.promise
  }
}

